WFJ.Data.add("spell", {
  [440212] = { "半径5ヤードに$N1のFrostダメージを与えます。", nil, 0x68d7f26f, nil, "um" },
  [440488] = { "ウォリアーの前方に衝撃波を放ち、前方扇状の$N2ヤード以内にいるすべての敵に$N1のダメージを与え、$D1スタンさせます。", "スタンしています。", 0x6860b6dd, 0x27f95286, "uu" },
  [440492] = { "外套にFresh Meatのルーンを刻みます：\n\n$I1\nBloodthirst、Mortal Strike、Shield Slamで対象にダメージを与えると、初回は100%、以降は毎回$N2%の確率でEnrage状態になり（Enraged状態が必要なアビリティが使用可能になります）、$D1の間、与えるPhysicalダメージが$N3%増加します。", nil, 0x5a6bf051, nil, "um" },
  [440494] = { "外套にSudden Deathのルーンを刻みます：\n\n$I1\n近接攻撃が命中すると、$N1%の確率でSudden Deathを得ます。Sudden Deathにより、対象の体力の状態に関係なくExecuteを一回使用できます。Sudden DeathによってExecuteが使用可能になった場合、Execute使用後に怒りが$N2残ります。", nil, 0x6d800699, nil, "um" },
  [440496] = { "外套にShockwaveのルーンを刻みます：\n\n$I1\nウォリアーの前方に衝撃波を放ち、$N1のダメージを与え、前方の円錐範囲$N2ヤード以内のすべての敵を$D1の間スタンさせます。", nil, 0x56e19117, nil, "um" },
  [440505] = { "$D1の間、服用者を透明にします。", nil, 0x3fdd20e3, nil, "um" },
  [440529] = { "Trapのアビリティと近接アビリティのマナコストを$N1%減少させます。さらに、クリティカルヒット時に$N2%の確率で、$D1の間、詠唱中もマナの回復の$N3%が続くようになります。", nil, 0xbc56e52f, nil, "um" },
  [440557] = { "外套にResourcefulnessのルーンを刻みます：\n\n$I1\nTrapアビリティと近接アビリティのマナコストを$N1%減少させます。さらに、クリティカルは$N2%の確率で、$D1の間、詠唱中もマナの回復の$N3%が継続するようにします。", nil, 0x5c9e589a, nil, "um" },
  [440560] = { "外套にImproved Volleyのルーンを刻みます：\n\n$I1\nVolleyのマナコストを$N1%減少させ、クールダウンを$N2%短縮し、ダメージを$N3%増加させ、ダメージ攻撃による詠唱の遅延を受けなくなります。さらに、Volleyはダメージを与えるたびに、遠隔Attack Powerの$N4%を追加ダメージとして与えます。", nil, 0x20ba9081, nil, "um" },
  [440563] = { "外套にHit and Runのルーンを刻みます：\n\n$I1\nRaptor Strike使用後、$D1の間、移動速度が$N1%上昇します。\n\nペットのダメージ系アビリティは対象をRabid Frenzy状態にし、$D2の間、その近接攻撃力を$N3上昇させますが、アーマーを$N4減少させます。Rabid状態の敵は逃走せず、FearとHorrorの効果を無視します。", nil, 0x15040a9f, nil, "um" },
  [440586] = { "$D1の間、対象をスタンさせます。", nil, 0xb330d181, nil, "um" },
  [440630] = { "外套にFeral Spiritのルーンを刻みます：\n\n$I1\nシャーマンの指揮下にある二体のSpirit Wolvesを召喚します。効果時間は$D1です。", nil, 0x3a18cf25, nil, "um" },
  [440632] = { "Cat、Bear、Dire Bearフォームでのみ、Attack Powerが+$N1されます。", nil, 0xa798bce2, nil, "um" },
  [440634] = { "外套にStorm, Earth, and Fireのルーンを刻みます：\n\n$I1\nChain Lightningのクールダウンを$N1%短縮し、Earthbind Totemが設置時に対象を$D1の間移動不能にするようになり、Flame Shockの持続ダメージを$N3%増加させます。", nil, 0xb99a4382, nil, "um" },
  [440658] = { "盾で対象を殴りつけ、ブロック値に基づくHolyダメージに加えて、さらに$N1のダメージを与えます。", nil, 0x675f9fa9, nil, "um" },
  [440788] = { "外套にShield of Righteousnessのルーンを刻みます：\n\n$I1\n盾で対象を強打し、ブロック値に基づくHolyダメージに加えて、さらに$N1のダメージを与えます。", nil, 0xb62d614f, nil, "um" },
  [440790] = { "外套にShock and Aweのルーンを刻みます：\n\n$I1\nRighteous Furyが有効でない間、Holy Shockでダメージを与えると、知力の$N1%をSpell Damageとして得て、$D1の間、生み出す脅威が$N2%減少します。\n\nInfusion of Lightが刻まれている場合、$D2の間Sunlightを得ます。\n\n$I2\nSunlightにより、Divine Storm、Crusader Strike、およびプレイヤー以外が操作する対象への近接攻撃が、神聖呪文パワーの$N5%に等しい追加のHolyダメージを与えます。", nil, 0x21f37d6a, nil, "um" },
  [440792] = { "外套にRighteous Vengeanceのルーンを刻みます：\n\n$I1\nJudgementまたはCrusader Strikeがクリティカルになると、対象は$D1かけて$N1%の追加ダメージを受けます。", nil, 0xdd37e14e, nil, "um" },
  [440802] = { "渦巻く氷の球を放ちます。球は$D1かけて素早く前進します。移動中、球は$N2秒ごとに、通過したすべての敵に$N3のFrost Damageを与え、移動速度を$N4%低下させるChillを付与します。初めて敵にダメージを与えると、球の動きは遅くなり、100%の確率でFingers of Frostのルーンを発動させます。", nil, 0xcb2a6d8e, nil, "um" },
  [440809] = { nil, "移動速度が$N1%低下しています。", nil, 0x09876d53, "mu" },
  [440827] = { "泡立つ大釜に投げ込むと、有毒ガスの爆発を起こします。ステルスは解除されません。", nil, 0x5d2eeb16, nil, "um" },
  [440829] = { "肉と骨の供物を組み合わせます。", nil, 0x49295518, nil, "um" },
  [440830] = { "空の紋章に血の魔法の精髄を込めます。", nil, 0x9ddd6f51, nil, "um" },
  [440841] = { "供物が隠された墓を明らかにします。", "供え物が隠された墓の場所を明らかにします。", 0x4a6817a6, 0x4a6817a6, "uu" },
  [440858] = { "外套にFrozen Orbのルーンを刻みます：\n\n$I1\n渦巻く氷のオーブを放ちます。オーブは$D1かけて素早く前進します。移動中、オーブは$D2ごとに$N3のFrost Damageを与え、通過したすべての敵に移動速度を$N4%低下させるChillを付与します。初めて敵にダメージを与えると、オーブの移動は遅くなり、100%の確率でFingers of Frostのルーンを発動させます。", nil, 0xf8b56c74, nil, "um" },
  [440870] = { "Soul Fire呪文のクールダウンを$N1%短縮します。体力が$N2%未満の敵にShadow BoltまたはSearing Painを唱えると、その敵が受けるダメージが$N3%増加し、さらに次の$D1の間、Soul Fire呪文の詠唱時間が$N5%短縮され、Soul Shardを消費しなくなります。", nil, 0x7455458a, nil, "um" },
  [440892] = { "$D1の間、対象に呪いをかけ、Magic耐性を$N2低下させ、受けるMagicダメージを$N3%増加させます。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。", "Magic耐性が$N1低下します。受けるMagicダメージが$N2%増加します。", 0x68afc919, 0x96faf3fe, "uu" },
  [440922] = { "ブーツにDecimationのルーンを刻みます：\n\n$I1\nSoul Fireのクールダウンを$N1%短縮します。体力が$N2%未満の敵にShadow BoltまたはSearing Painを詠唱すると、与えるダメージが$N3%増加し、次の$D1の間、Soul Fireの詠唱時間が$N5%短縮され、Soul Shardを消費しなくなります。", nil, 0x19ab4ac7, nil, "um" },
  [440924] = { "外套にMark of Chaosのルーンを刻みます：\n\n$I1\n対象を$D1の間呪い、Magic耐性を$N2減少させ、受けるMagicダメージを$N3%増加させます。一つの対象に対して、ウォーロックごとに有効にできるCurseは一つだけです。", nil, 0x050e05a1, nil, "um" },
  [440926] = { "外套にInfernal Armorのルーンを刻みます：\n\n$I1\n魂が悪魔のエネルギーで満たされ、受けるMagicダメージをすべて、アーマーによるPhysicalダメージ軽減率の$N1%に等しい割合だけ軽減します。効果時間は$D1です。", nil, 0x32bd63f1, nil, "um" },
